-- 0379 PROD CHECK (before), read-only, ONE statement: npx --yes supabase@2.120.0 db query --linked -f scripts/ops/harness/armada-battle/before.sql
-- IT DEPLOYS AFTER 0375 (the attacks work) AND 0378: head 20260818000378. Attacks may be LIT by then, and the file takes the switch as it finds it.
-- Wanted: 13 rows; EVERY old_times 1 and new_times 0 (a 0 in old_times means a file deployed since batch 6 re-cut a line 0379 anchors on: do not deploy, re-cut the hunk);
-- made 0 (none of 0379's seven functions yet); how_check lists OPENED, ESCORT, CALLED and not ARMADA; armada_sides 0;
-- attack is printed (true or false: both are fine); fighting is printed (battles being fought now, at most 5 counted: the deploy holds public.battle_sides for about a
-- second, so a quiet moment is kinder, and a lone fleet's battle goes on as it was); armadas and armada_fleets are printed (how many armadas stand);
-- pvp "both refusals stand".
-- Keep `bodies` (each cut body's md5): the dev-log holds the local values on batch 6.
-- Generated by scripts/ops/harness/armada-battle/gen-checks.mjs from the migration's own hunks. Only the catalog, one knob and whether a row exists in four tables are read.
begin transaction read only;
with h(fn, ord, old, new) as (values
  ('public.attack_for(uuid,uuid,uuid,integer,timestamp with time zone)'::text, 1, $h$  foreach v_fleet in array array[least(p_fleet, p_target), greatest(p_fleet, p_target)] loop
$h$, $h$  -- 0379 (docs/ARMADA.md section 7): a fleet of an armada attacks with every fleet of hers that is there. Each of them is judged before anything moves, and one refused
  -- refuses the attack under her name (public.attack_armada_gates). A fleet in no armada: one primary-key probe, and nothing.
  perform public.attack_armada_gates(p_player, p_fleet, p_now);
  foreach v_fleet in array array[least(p_fleet, p_target), greatest(p_fleet, p_target)] loop
$h$),
  ('public.attack_for(uuid,uuid,uuid,integer,timestamp with time zone)'::text, 2, $h$    'resolves_at', (select b.resolves_at from public.battles b where b.id = v_battle));
$h$, $h$    'resolves_at', (select b.resolves_at from public.battles b where b.id = v_battle))
    || public.battle_armada_note(v_battle);   -- 0379: an armada's battle says her name and her fleets, and the word is the armada's; any other battle: {}
$h$),
  ('public.battle_open(text,uuid,uuid,timestamp with time zone)'::text, 1, $h$  foreach v_fleet in array array[p_attacker, p_defender] loop
$h$, $h$  -- 0379 (docs/ARMADA.md section 7): the fleets of her armada that are there join her side now, before the sheet is frozen, and are stopped by this same loop
  foreach v_fleet in array array[p_attacker, p_defender] || public.battle_armada_join(v_id, p_kind, p_attacker, p_now) loop
$h$),
  ('public.battle_sheet_freeze(uuid,timestamp with time zone)'::text, 1, $h$  v_st := public.battle_opening_stance(v_def);
$h$, $h$  perform public.battle_armada_sheet(p_battle);   -- 0379: an armada's sheet names her and her fleets, and its word reads all of them; any other sheet: nothing
  v_st := public.battle_opening_stance(v_def);
$h$),
  ('public.battle_resolve(uuid,timestamp with time zone)'::text, 1, $h$    if s.side = 'ATTACKER' and not s.is_npc then
$h$, $h$    if s.side = 'ATTACKER' and not s.is_npc   -- 0379: one report a battle, under the fleet that attacked: a fleet that joined as her armada sends none
       and not exists (select 1 from public.battle_sides x where x.battle_id = p_battle and x.fleet_id = s.fleet_id and x.how = 'ARMADA') then
$h$),
  ('public.attack_close(uuid,jsonb,timestamp with time zone)'::text, 1, $h$   where bs.battle_id = p_battle and bs.side = 'ATTACKER';
$h$, $h$   where bs.battle_id = p_battle and bs.side = 'ATTACKER' and bs.how = 'OPENED';   -- 0379: the fleet that attacked; her armada's fleets are public.attack_armada_close's
$h$),
  ('public.attack_close(uuid,jsonb,timestamp with time zone)'::text, 2, $h$  return jsonb_build_object('loot', v_gold, 'crew_lost', v_lost);
$h$, $h$  return jsonb_build_object('loot', v_gold, 'crew_lost', v_lost)
      || public.attack_armada_close(p_battle, p_fight, v_gold, v_lost);   -- 0379: her armada's fleets lose their hands by the same row, and each fleet's share is said; no armada: {}
$h$),
  ('public.battle_log(jsonb,jsonb,text)'::text, 1, $h$  return (v_log - 'end') || '{"atk": true}'::jsonb || case when v_end is null then '{}'::jsonb else jsonb_build_object('end', v_end) end;
$h$, $h$  return (v_log - 'end') || '{"atk": true}'::jsonb || case when v_end is null then '{}'::jsonb else jsonb_build_object('end', v_end) end
      || case when p_sheet ? 'fleets' then jsonb_build_object('fleets', p_sheet->'fleets') else '{}'::jsonb end;   -- 0379: an armada's log names her fleets above their ships, as a raid's does (0367)
$h$),
  ('world.battle(uuid)'::text, 1, $h$   where bs.fleet_id = p_fleet and bs.how = 'OPENED' and f.player_id = v_player and bt.sheet is not null
$h$, $h$   where bs.fleet_id = p_fleet and bs.how in ('OPENED', 'ARMADA') and f.player_id = v_player and bt.sheet is not null   -- 0379: any fleet of hers in it reads the battle
$h$),
  ('world.battle(uuid)'::text, 2, $h$                                    'navy', b.result #> '{navy,line}') end;
$h$, $h$                                    'navy', b.result #> '{navy,line}') end
    || public.battle_armada_view(b.id, p_fleet);   -- 0379: her armada's name, her fleets, the side's stance and, closed, each fleet's share; no armada: {}
$h$),
  ('public.navy_close(uuid,timestamp with time zone)'::text, 1, $h$  select count(*) filter (where bs.how <> 'OPENED' and bs.arrives_at <= b.resolves_at),
$h$, $h$  select count(*) filter (where bs.how not in ('OPENED', 'ARMADA') and bs.arrives_at <= b.resolves_at),   -- 0379: her own armada is no navy
$h$),
  ('public.navy_close(uuid,timestamp with time zone)'::text, 2, $h$         bool_or(bs.how <> 'OPENED' and bs.arrives_at <= b.resolves_at or ($h$, $h$         bool_or(bs.how not in ('OPENED', 'ARMADA') and bs.arrives_at <= b.resolves_at or ($h$),
  ('public.battle_navy_served(uuid)'::text, 1, $h$                     join public.battle_sides o on o.battle_id = b.id and o.how <> 'OPENED' and o.arrives_at <= b.resolves_at
$h$, $h$                     join public.battle_sides o on o.battle_id = b.id and o.how not in ('OPENED', 'ARMADA') and o.arrives_at <= b.resolves_at   -- 0379: her own armada is no help coming to the other side
$h$)
), d as (
  select h.*, replace(pg_get_functiondef(to_regprocedure(h.fn)), chr(13), '') as def from h
)
select fn, ord,
       (length(def) - length(replace(def, old, ''))) / length(old) as old_times,
       (length(def) - length(replace(def, new, ''))) / length(new) as new_times,
       (select count(*) from unnest(array['public.battle_armada(uuid,timestamp with time zone)', 'public.attack_armada_gates(uuid,uuid,timestamp with time zone)', 'public.battle_armada_join(uuid,text,uuid,timestamp with time zone)', 'public.battle_armada_sheet(uuid)', 'public.battle_armada_note(uuid)', 'public.attack_armada_close(uuid,jsonb,bigint,bigint)', 'public.battle_armada_view(uuid,uuid)']) f where to_regprocedure(f) is not null) as made,
       (select pg_get_constraintdef(c.oid) from pg_constraint c where c.conrelid = to_regclass('public.battle_sides') and c.conname = 'battle_sides_how_check') as how_check,
       public.attack_on() as attack,
       (select count(*) from (select 1 from public.battles b where b.status = 'FIGHTING' limit 5) q) as fighting,
       (select count(*) from (select 1 from public.battle_sides bs where bs.how not in ('OPENED', 'ESCORT', 'CALLED') limit 5) q) as armada_sides,
       (select count(*) from (select 1 from public.armadas limit 50) q) as armadas,
       (select count(*) from (select 1 from public.armada_fleets limit 300) q) as armada_fleets,
       case when (select p.prosrc from pg_proc p where p.oid = to_regprocedure('public.battle_open(text,uuid,uuid,timestamp with time zone)')) like '%E_HUMAN_TARGET: no player fights another player%'
             and (select p.prosrc from pg_proc p where p.oid = to_regprocedure('public.attack_for(uuid,uuid,uuid,integer,timestamp with time zone)')) like '%E_HUMAN_TARGET%no player attacks another player%'
            then 'both refusals stand' else 'A REFUSAL IS GONE' end as pvp,
       (select jsonb_object_agg(f, md5(replace(pg_get_functiondef(to_regprocedure(f)), chr(13), ''))) from unnest(array['public.attack_for(uuid,uuid,uuid,integer,timestamp with time zone)', 'public.battle_open(text,uuid,uuid,timestamp with time zone)', 'public.battle_sheet_freeze(uuid,timestamp with time zone)', 'public.battle_resolve(uuid,timestamp with time zone)', 'public.attack_close(uuid,jsonb,timestamp with time zone)', 'public.battle_log(jsonb,jsonb,text)', 'world.battle(uuid)', 'public.navy_close(uuid,timestamp with time zone)', 'public.battle_navy_served(uuid)']) f) as bodies,
       (select max(version) from supabase_migrations.schema_migrations) as head
  from d order by fn, ord;
commit;
